<?php
require_once __DIR__.'/../includes/layout.php';$u=require_login('student');$q=db()->prepare('SELECT a.*,o.title,o.type,o.city,r.company_name FROM applications a JOIN offers o ON o.id=a.offer_id JOIN recruiter_profiles r ON r.user_id=o.recruiter_id WHERE a.student_id=? ORDER BY a.applied_at DESC');$q->execute([$u['id']]);$rows=$q->fetchAll();page_header('Mes candidatures');
?><div class="table-wrap"><table><thead><tr><th>Offre</th><th>Entreprise</th><th>Date</th><th>Statut</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['title'])?></td><td><?=h($r['company_name'])?></td><td><?=h($r['applied_at'])?></td><td><span class="pill"><?=h(['pending'=>'En attente','interview'=>'Invité à un entretien','rejected'=>'Non retenu'][$r['status']])?></span></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><p>Aucune candidature pour le moment.</p><?php endif;page_footer();?>